/** Body of POST /comments. The password is generated by the browser (see CommentPasswordService). */
export interface CommentCreateDTO {
  pseudo: string;
  comment: string;
  coordinateX: number;
  coordinateY: number;
  password: string;
}

/** Body of PUT /comments/{id}: new text/position, authorized by the message's password. */
export interface CommentUpdateDTO {
  comment: string;
  coordinateX: number;
  coordinateY: number;
  password: string;
}

export interface CommentVerifyResponseDTO {
  valid: boolean;
}
